-- User approved 2026-10-31: reset all three configured slot tables to NEW backend defaults.
-- Only table 0 relative-weight rows; wallet, table limits and legacy profiles are untouched.
-- Requires database backup. Concurrent edits cause rollback; repeat execution is safe.
DROP PROCEDURE IF EXISTS reset_slot_defaults_1077;
DELIMITER $$
CREATE PROCEDURE reset_slot_defaults_1077()
BEGIN
 DECLARE n INT DEFAULT 0;
 DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
 CREATE TEMPORARY TABLE expected_weights (GAME_ID INT,TableId INT,HandType INT,PayoutMultiplier INT,ProbabilityBasis INT,Enabled INT, PRIMARY KEY(GAME_ID,TableId,HandType));
 START TRANSACTION;
 SELECT COUNT(*) INTO n FROM cardpayoutprofile p JOIN expected_weights e USING(GAME_ID,TableId,HandType,PayoutMultiplier,ProbabilityBasis,Enabled);
 IF n=141 AND (SELECT COUNT(*) FROM cardpayoutprofile WHERE GAME_ID IN (16,40,53) AND TableId=0 AND HandType>=1000)=141 THEN
  DELETE FROM cardpayoutprofile WHERE GAME_ID IN (16,40,53) AND TableId=0 AND HandType>=1000;
 END IF;
 DELETE FROM expected_weights;
 SELECT COUNT(*) INTO n FROM cardpayoutprofile p JOIN expected_weights e USING(GAME_ID,TableId,HandType,PayoutMultiplier,ProbabilityBasis,Enabled);
 IF n<>119 OR (SELECT COUNT(*) FROM cardpayoutprofile WHERE GAME_ID IN (16,40,53) AND TableId=0 AND HandType>=1000)<>119 THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Slot profile differs from reviewed before/after snapshots; no changes committed';
 END IF;
 COMMIT;
 DROP TEMPORARY TABLE expected_weights;
END$$
DELIMITER ;
CALL reset_slot_defaults_1077();
DROP PROCEDURE reset_slot_defaults_1077;
